    out.Boolean("buffer_physical_bytes", first.header.hDevice == reinterpret_cast<HANDLE>(kNativeDevice) && first.data.mouse.lLastX == kPhysicalX);
    out.Number("buffer_memory_dx", first.data.mouse.lLastX); out.Number("buffer_memory_dy", first.data.mouse.lLastY);
